// swift-tools-version:6.0
import PackageDescription

/// `CoreLoopAcceptance` is the sign-off gate for `Docs/Design/CORE_LOOP.md`.
///
/// One end-to-end walk of the loop — open, calibrate, measure, export, undo — on a heavy A1
/// construction sheet, the Synthetic Roof Plan of `ZPDFTestingSupport` (16 341 vector
/// primitives, a 100 mm control ruler, a fictional title block), generated by the test with a
/// versioned, pinned identity. Nothing here is mocked: the walk drives the same presenters the
/// UI binds to and the same engines the app ships, the calibration anchors are snapped against
/// linework the file actually draws, and every expected number is derived by hand from the
/// picked page coordinates and the calibrated scale, in the test comments.
///
/// The package depends on `ZenitPDFAppKit` — the application library itself — because the
/// loop's open step (`DocumentSessionLoader`, `PageRasterSource`) and its CSV export step
/// (`LedgerCSVExport`) live there, and an acceptance test that reimplements either is not
/// testing the product.
let package = Package(
    name: "CoreLoopAcceptance",
    platforms: [.macOS(.v14)],
    dependencies: [
        .package(path: "../../Apps/ZenitPDF"),
        .package(path: "../../Packages/ZPDFAppCore"),
        .package(path: "../../Packages/ZPDFContracts"),
        .package(path: "../../Packages/ZPDFGeometry"),
        .package(path: "../../Packages/ZPDFPDFKitBridge"),
        .package(path: "../../Packages/ZPDFVectorExtraction"),
        .package(path: "../../Packages/ZPDFSnapEngine"),
        .package(path: "../../Packages/ZPDFUIPresentation"),
